     if (!ctx.slug) return;
     let apiUrl = 'https://api.hiweb.vn/api/v1/wedding/invitation?slug=' + encodeURIComponent(ctx.slug);
     if (ctx.wishes_password) apiUrl += '&passwordWishes=' + encodeURIComponent(ctx.wishes_password);
