  function fallbackCopyText(text) {
    var ta = document.createElement('textarea');
    ta.value = text;
    ta.style.cssText = 'position:fixed;left:-9999px;top:-9999px;opacity:0;';
    document.body.appendChild(ta);
    ta.focus();
    ta.select();
    var ok = false;
    try { ok = document.execCommand('copy'); } catch (_) { /* noop */ }
    document.body.removeChild(ta);
    return ok;
  }

  function bindQrCopyButtons() {

    const grid = root.querySelector('#chrome-wedding_gift-modal [data-gift-rows]');
    if (!grid || grid.dataset.copyBound) return;
    grid.dataset.copyBound = '1';
    grid.querySelectorAll('[data-copy]').forEach((b) => {
      b.addEventListener('click', () => {
        const text = b.dataset.copy;
        const oldHTML = b.innerHTML;
        const showCopied = () => {
          b.innerHTML = '<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"><polyline points="20 6 9 17 4 12"/></svg> Đã chép';
          setTimeout(() => { b.innerHTML = oldHTML; }, 1400);
        };
        if (navigator.clipboard && navigator.clipboard.writeText) {
          navigator.clipboard.writeText(text).then(showCopied).catch(() => {
            fallbackCopyText(text);
            showCopied();
          });
        } else {
          fallbackCopyText(text);
          showCopied();
        }
      }, { passive: true });
    });
  }

  function addGiftAccountRow() {
    const brideRow = root.querySelector('#chrome-wedding_gift-modal [data-gift-bride]');
    if (!brideRow) return;
    if (brideRow.style.display !== 'none' && !brideRow.style.display.includes('none')) return;
    brideRow.style.removeProperty('display');
    delete brideRow.dataset.copyBound;
    if (typeof bindQrCopyButtons === 'function') bindQrCopyButtons();
    if (typeof applyGiftSingleRecipientLayout === 'function') applyGiftSingleRecipientLayout();
  }

  window.addGiftAccountRow = addGiftAccountRow;

  window.addEventListener('message', function(event) {
    const data = event && event.data ? event.data : {};
    if (data.type === 'ADD_GIFT_ACCOUNT') {
      simpleOpenChromeModal('wedding_gift');
      addGiftAccountRow();
    }
    if (data.type === 'REMOVE_GIFT_ACCOUNT') {
      const brideRow = root.querySelector('#chrome-wedding_gift-modal [data-gift-bride]');
      if (brideRow) {
        brideRow.style.setProperty('display', 'none', 'important');
        delete brideRow.dataset.copyBound;
      }
      if (typeof applyGiftSingleRecipientLayout === 'function') applyGiftSingleRecipientLayout();
    }
  });

  // Gift single-recipient QR: nếu chỉ còn 1 block gift đang hiển thị => QR to + giảm khoảng trắng
  // Gift double-full: nếu đúng 2 block => modal full + thông tin lớn, ẩn nút thêm
  function applyGiftSingleRecipientLayout() {
    try {
      const giftModal = root.querySelector('#chrome-wedding_gift-modal');
      if (!giftModal) return;
      const visibleRows = giftModal.querySelectorAll('[data-gift-default]:not([style*="display: none"]), [data-gift-bride]:not([style*="display: none"]), [data-gift-evt]:not([style*="display: none"])');
      const count = Array.from(visibleRows).filter(el => {
        const style = el.getAttribute('style') || '';
        return !style.includes('display: none') && !style.includes('display:none');
      }).length;
      giftModal.classList.remove('gift-single-qr', 'gift-horizontal-rows', 'gift-double-full');
      if (count <= 1) {
        giftModal.classList.add('gift-single-qr');
      } else if (count === 2) {
        giftModal.classList.add('gift-double-full');
      } else if (count >= 3) {
        giftModal.classList.add('gift-horizontal-rows');
      }
    } catch (e) {
      // noop
    }
  }


  function resolveLockSlug() {
    const ls = window.invitationLockStatus || {};
    return firstNonEmpty(
      ls.slug,
      ls.invitation_slug,
      window.invitation_slug,
      resolveSlugFromDom(),
      resolveSlugFromLocation(),
      resolveSlugFromHost(),
      getRemoteValue('slug'),
      getQueryValue(['slug', 'invitationSlug', 'invitation_slug']),
    );
  }

  function isWishLocked() {
    const ls = window.invitationLockStatus || {};
    const slug = resolveLockSlug();
    if (slug && typeof sessionStorage !== 'undefined') {
      try { if (sessionStorage.getItem('invitation_' + slug + '_wishes')) return false; } catch (e) {}
    }
    var wv = String(ls.wishes_visibility || '').toLowerCase();
    if (wv && wv !== 'password') return false;
    if (!!(ls.wishesPassword || ls.password_wishes)) return true;
    const flag = ls.wishesLocked !== undefined ? ls.wishesLocked : ls.wishes_locked;
    return flag === undefined ? false : !!flag;
  }

  function isRsvpLocked() {
    const ls = window.invitationLockStatus || {};
    const slug = resolveLockSlug();
    if (slug && typeof sessionStorage !== 'undefined') {
      try { if (sessionStorage.getItem('invitation_' + slug + '_rsvp')) return false; } catch (e) {}
    }
    var rv = String(ls.rsvp_visibility || '').toLowerCase();
    if (rv && rv !== 'password') return false;
    if (!!(ls.rsvpPassword || ls.password_rsvp)) return true;
    const flag = ls.rsvpLocked !== undefined ? ls.rsvpLocked : (ls.rsvp_locked !== undefined ? ls.rsvp_locked : (ls.rsvpsLocked !== undefined ? ls.rsvpsLocked : ls.rsvps_locked));
    return flag === undefined ? false : !!flag;
  }

  function syncWishLockState() {
    if (typeof window.invitationLockStatus === 'undefined') {
      window.invitationLockStatus = {};
    }
    const viewLink = $('chrome-wish-view-link');
    const unlockSection = $('chrome-wish-unlock-section');
    const viewList = $('chrome-wish-view-list');
    const downloadLink = $('chrome-wish-download-link');
    const listDivider = document.getElementById('chrome-wish-list-divider');
    const dividerLocked = $('chrome-wish-divider-locked');
    const wishErr = $('chrome-wish-unlock-error');
    if (!viewLink || !viewList) return;
    const isLocked = isWishLocked();
    viewLink.style.display = isLocked ? 'inline-flex' : 'none';
    if (downloadLink) downloadLink.style.display = isLocked ? 'none' : 'inline-flex';
    if (unlockSection) {
      unlockSection.style.display = 'none';
      unlockSection.style.maxHeight = '0';
      unlockSection.classList.remove('open');
    }
    if (wishErr) { wishErr.style.display = 'none'; wishErr.textContent = ''; }
    if (dividerLocked) dividerLocked.style.display = isLocked ? '' : 'none';
    viewList.style.display = '';
    if (listDivider) listDivider.style.display = isLocked ? 'none' : '';
  }

