    if (!settings.show_quantity_selector) css += '.quantity-selector,.item-quantity,.qty-selector,.hiweb-qty{display:none!important}';
    if (!settings.show_cart) css += '.shopping-cart,.cart-icon,.cart-button,.add-to-cart,.hiweb-cart,.cart-container,.cart-wrapper,[data-hiweb-cart]{display:none!important}';
