            var body = '<div class="overflow-x-auto"><table class="min-w-full text-left"><thead><tr class="border-b border-slate-200 text-[11px] font-black uppercase tracking-[0.16em] text-slate-500"><th class="px-3 py-3">Mã đơn</th><th class="px-3 py-3">Khách hàng</th><th class="px-3 py-3">Số điện thoại</th><th class="px-3 py-3">Địa chỉ</th><th class="px-3 py-3">Tổng tiền</th><th class="px-3 py-3">Thanh toán</th><th class="px-3 py-3">Trạng thái</th><th class="px-3 py-3">Ngày tạo</th><th class="px-3 py-3 text-right">Thao tác</th></tr></thead><tbody>';
